using System;
using System.Collections.Generic;
using System.Net.Http;
using System.Threading;
using System.Threading.Tasks;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Logging;
using Microsoft.Extensions.Options;

namespace MeridianStudio.Implementation.IntegrateWithExistingTransactionProcessingSystems
{
    public sealed record TransactionProcessingOptions
    {
        public string ApiEndpoint { get; init; } = "";
        public string ApiKey { get; init; } = "";
        public int TimeoutSeconds { get; init; } = 30;
    }

    public record TransactionRecord(string TransactionId, decimal Amount, string Currency, DateTime Timestamp, string SenderAccount, string ReceiverAccount);

    public record IntegrationResponse(bool Success, string Message);

    public interface ITransactionProcessingService
    {
        Task<IntegrationResponse> SendTransactionAsync(TransactionRecord transaction, CancellationToken cancellationToken = default);
        Task<IEnumerable<TransactionRecord>> GetRecentTransactionsAsync(int count, CancellationToken cancellationToken = default);
    }

    public class TransactionProcessingService : ITransactionProcessingService
    {
        private readonly ILogger<TransactionProcessingService> _logger;
        private readonly TransactionProcessingOptions _options;
        private readonly HttpClient _httpClient;

        public TransactionProcessingService(ILogger<TransactionProcessingService> logger, IOptions<TransactionProcessingOptions> options, IHttpClientFactory httpClientFactory)
        {
            _logger = logger;
            _options = options.Value;
            _httpClient = httpClientFactory.CreateClient("TransactionProcessingClient");
            _httpClient.BaseAddress = new Uri(_options.ApiEndpoint);
            _httpClient.DefaultRequestHeaders.Add("X-Api-Key", _options.ApiKey);
            _httpClient.Timeout = TimeSpan.FromSeconds(_options.TimeoutSeconds);
        }

        public async Task<IntegrationResponse> SendTransactionAsync(TransactionRecord transaction, CancellationToken cancellationToken = default)
        {
            try
            {
                _logger.LogInformation("Sending transaction {TransactionId} to processing system.", transaction.TransactionId);
                var response = await _httpClient.PostAsJsonAsync("/transactions", transaction, cancellationToken).ConfigureAwait(false);

                if (response.IsSuccessStatusCode)
                {
                    _logger.LogInformation("Successfully sent transaction {TransactionId}.", transaction.TransactionId);
                    return new IntegrationResponse(true, "Transaction sent successfully.");
                }
                else
                {
                    var errorContent = await response.Content.ReadAsStringAsync(cancellationToken).ConfigureAwait(false);
                    _logger.LogError("Failed to send transaction {TransactionId}. Status: {StatusCode}, Error: {ErrorContent}", transaction.TransactionId, response.StatusCode, errorContent);
                    return new IntegrationResponse(false, $"Failed to send transaction: {response.StatusCode} - {errorContent}");
                }
            }
            catch (HttpRequestException ex)
            {
                _logger.LogError(ex, "Network error while sending transaction {TransactionId}.", transaction.TransactionId);
                return new IntegrationResponse(false, $"Network error: {ex.Message}");
            }
            catch (TaskCanceledException ex)
            {
                _logger.LogError(ex, "Request timed out while sending transaction {TransactionId}.", transaction.TransactionId);
                return new IntegrationResponse(false, "Request timed out.");
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "An unexpected error occurred while sending transaction {TransactionId}.", transaction.TransactionId);
                return new IntegrationResponse(false, $"An unexpected error occurred: {ex.Message}");
            }
        }

        public async Task<IEnumerable<TransactionRecord>> GetRecentTransactionsAsync(int count, CancellationToken cancellationToken = default)
        {
            try
            {
                _logger.LogInformation("Fetching {Count} recent transactions from processing system.", count);
                var response = await _httpClient.GetAsync($"/transactions/recent?count={count}", cancellationToken).ConfigureAwait(false);

                if (response.IsSuccessStatusCode)
                {
                    var transactions = await response.Content.ReadFromJsonAsync<List<TransactionRecord>>(cancellationToken: cancellationToken).ConfigureAwait(false);
                    _logger.LogInformation("Successfully fetched {Count} recent transactions.", transactions?.Count ?? 0);
                    return transactions ?? new List<TransactionRecord>();
                }
                else
                {
                    var errorContent = await response.Content.ReadAsStringAsync(cancellationToken).ConfigureAwait(false);
                    _logger.LogError("Failed to fetch recent transactions. Status: {StatusCode}, Error: {ErrorContent}", response.StatusCode, errorContent);
                    return new List<TransactionRecord>();
                }
            }
            catch (HttpRequestException ex)
            {
                _logger.LogError(ex, "Network error while fetching recent transactions.");
                return new List<TransactionRecord>();
            }
            catch (TaskCanceledException ex)
            {
                _logger.LogError(ex, "Request timed out while fetching recent transactions.");
                return new List<TransactionRecord>();
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "An unexpected error occurred while fetching recent transactions.");
                return new List<TransactionRecord>();
            }
        }
    }

    public static class TransactionProcessingServiceCollectionExtensions
    {
        public static IServiceCollection AddTransactionProcessingService(this IServiceCollection services, Action<TransactionProcessingOptions> configureOptions)
        {
            services.Configure(configureOptions);
            services.AddHttpClient("TransactionProcessingClient");
            services.AddScoped<ITransactionProcessingService, TransactionProcessingService>();
            return services;
        }
    }
}
